CREATE TRIGGER RefCusApplicability_Combined
	ON RefCusApplicability
	FOR INSERT, UPDATE, DELETE
	AS
	IF (SELECT CASE WHEN EXISTS(SELECT 1 FROM INSERTED) AND NOT EXISTS(SELECT 1 FROM DELETED) THEN 1 ELSE 0 end) = 1
	BEGIN
		UPDATE t SET
		ZZT_DataSetPK = COALESCE(ZX1_DataSetPK, ZZ2_DataSetPK, ZY2_DataSetPK, ZZH_DataSetPK),
		ZZT_DataSetCode = CASE WHEN ZX1_DataSetPK IS NOT NULL THEN ZX1_DataSetCode ELSE CASE WHEN ZZ2_DataSetPK IS NOT NULL THEN ZZ2_DataSetCode ELSE CASE WHEN ZY2_DataSetPK IS NOT NULL THEN ZY2_DataSetCode ELSE CASE WHEN ZZH_DataSetPK IS NOT NULL THEN ZZH_DataSetCode END END END END 
		FROM RefCusApplicability t
		JOIN inserted ON t.ZZT_PK = inserted.ZZT_PK
		LEFT JOIN RefCusCondition ON inserted.ZZT_ZX1_Conditions = ZX1_PK
		LEFT JOIN RefCusRate ON inserted.ZZT_ZZ2_Rate = ZZ2_PK
		LEFT JOIN RefCusTariffAdditionalCode ON inserted.ZZT_ZY2_AdditionalCode = ZY2_PK
		LEFT JOIN RefCusTariffRelationship ON inserted.ZZT_ZZH_TariffRelationship = ZZH_PK
	END

	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT t.ZZT_DataSetPK, t.ZZT_DataSetCode
	FROM RefCusApplicability t
	JOIN inserted ON t.ZZT_PK = inserted.ZZT_PK
	UNION
	SELECT ZZT_DataSetPK, ZZT_DataSetCode
	FROM deleted

	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN @sourcePK ON RVC_ParentPK = PK AND RVC_ParentCode = TablePrefix
	WHERE RVC_IsPublished = 1

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO

CREATE TRIGGER RefCusApplicability_DataProcessingResult_Delete
	ON RefCusApplicability
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.ZZT_PK
	END
GO
